@@ -0,0 +1,11 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortByStart(items, startsAt = (item) => item.startsAt) {
+  const time = (item) => new Date(startsAt(item)).getTime();
+  return [...items].sort((a, b) => time(a) - time(b));
+}
+
+export function buildAgenda(events) {
+  const entries = events.map((event) => ({ event, card: createEventCard(event) }));
+  return sortByStart(entries, (entry) => entry.event.startsAt).map((entry) => entry.card);
+}

